    my @raw_lines = split /\n/, $raw, -1;
    my $clean = strip_go($raw);
    my @lines = split /\n/, $clean, -1;

    my $pkg = '';
    my %imports; # local_name => full_import_path
    for my $line (@lines) {
        if ($line =~ /^\s*package\s+(\w+)/) { $pkg = $1; last; }
    }
    for my $line (@lines) {
        if ($line =~ /^\s*import\s+"([^"]+)"/) {
            my $p = $1;
            my $local = (split /\//, $p)[-1];
            $local =~ s/-//g; # rough
            $imports{$local} = $p;
        }
        if ($line =~ /^\s*import\s+\(/) { last; } # handled below
    }
    # multi-line import block
    if ($clean =~ /import\s*\((.*?)\)/s) {
        my $block = $1;
        while ($block =~ /(?:"([^"]+)"|(\w+)\s+"([^"]+)")/g) {
            if ($1) {
                my $p = $1;
                my $local = (split /\//, $p)[-1];
                $imports{$local} = $p;
            } elsif ($2 && $3) {
                $imports{$2} = $3;
            }
        }
    }

    # derive package path from file location
    my $rel = $f; $rel =~ s/^\Q$REPO\E\/?//;
    my $pkgpath = $MODULE . '/' . $rel;
    $pkgpath =~ s/\/[^\/]+\.go$//;

    $file_info{$f} = {
        pkg => $pkg,
        pkgpath => $pkgpath,
        imports => \%imports,
        is_test => is_test_file($f),
        lines => \@lines,
        raw_lines => \@raw_lines,
    };
