#!/usr/bin/perl
use strict;
use warnings;

my $REPO = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

sub strip_go {
    my ($src) = @_;
    my $out = '';
    my $i = 0;
    my $len = length($src);
    while ($i < $len) {
        my $c = substr($src, $i, 1);
        my $c2 = ($i + 1 < $len) ? substr($src, $i + 1, 1) : '';
        if ($c eq '/' && $c2 eq '/') {
            $i += 2;
            while ($i < $len && substr($src, $i, 1) ne "\n") { $i++; }
            $out .= "\n" if $i < $len;
            next;
        }
        if ($c eq '/' && $c2 eq '*') {
            $i += 2;
            while ($i + 1 < $len && !(substr($src, $i, 1) eq '*' && substr($src, $i + 1, 1) eq '/')) {
                $out .= "\n" if substr($src, $i, 1) eq "\n";
                $i++;
            }
            $i += 2 if $i + 1 < $len;
            next;
        }
        if ($c eq '"') {
            $out .= ' ';
            $i++;
            while ($i < $len) {
                my $ch = substr($src, $i, 1);
                if ($ch eq '\\') { $i += 2; next; }
                last if $ch eq '"';
                $out .= "\n" if $ch eq "\n";
                $i++;
            }
            $i++ if $i < $len;
            next;
        }
        if ($c eq '`') {
            $out .= ' ';
            $i++;
            while ($i < $len && substr($src, $i, 1) ne '`') {
                $out .= "\n" if substr($src, $i, 1) eq "\n";
                $i++;
            }
            $i++ if $i < $len;
            next;
        }
        if ($c eq "'") {
            $out .= '  ';
            $i += 3;
            next;
        }
        $out .= $c;
        $i++;
    }
    return $out;
}

sub is_test { $_[0] =~ /_test\.go$/ }
sub is_internal_path {
    my ($f) = @_;
    $f =~ s/^\Q$REPO\E\/?//;
    $f =~ /^internal\//;
}

my @files = split /\n/, `find '$REPO' -name '*.go' -type f 2>/dev/null`;
chomp @files;

my %fi; # file => info

for my $f (@files) {
    open my $fh, '<', $f or die $f;
    my $raw = do { local $/; <$fh> };
    close $fh;
    my $clean = strip_go($raw);
    my @lines = split /\n/, $clean, -1;

    my ($pkg) = $clean =~ /^\s*package\s+(\w+)/m;
    $pkg //= '';

    my %imports;
    while ($clean =~ /import\s+(?:\(\s*)?(.*?)(?:\)\s*|(?=\n\s*(?:var|const|type|func|\w)))/sg) {
        my $block = $1;
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $path) = ($1, $2);
            if (!defined $alias || $alias eq '') {
                $alias = (split /\//, $path)[-1];
            }
            $imports{$alias} = $path;
        }
    }

    my $rel = $f; $rel =~ s/^\Q$REPO\E\/?//;
    my $pkgpath = $MODULE . '/' . $rel;
    $pkgpath =~ s/\/[^\/]+\.go$//;

    $fi{$f} = {
        pkg => $pkg, pkgpath => $pkgpath, imports => \%imports,
        is_test => is_test($f), clean => $clean, lines => \@lines,
    };
}

# reverse map import path -> default local name
my %path_default_name;
for my $f (keys %fi) {
    for my $alias (keys %{ $fi{$f}{imports} }) {
        $path_default_name{ $fi{$f}{imports}{$alias} } = $alias;
    }
}

# Parse declarations (multiline func)
my %decls;      # id => info
my %by_pkg_name; # "$pkgpath\tFUNC\t$name" => id
my %by_pkg_recv; # "$pkgpath\t$recv\t$name" => id
my $nid = 0;

for my $f (keys %fi) {
    next unless is_internal_path($f);
    my $info = $fi{$f};
    while ($info->{clean} =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/g) {
        my ($recv, $name) = ($1, $2);
        next if $name eq 'init';
        my $pos = pos($info->{clean});
        my $prefix = substr($info->{clean}, 0, $pos);
        my $line = ($prefix =~ tr/\n//) + 1;
        my $recv_type = '';
        if (defined $recv && $recv ne '') {
            $recv_type = extract_recv($recv);
        }
        my $id = ++$nid;
        my $qual = $recv_type ? "($recv_type).$name" : $name;
        $decls{$id} = {
            pkgpath => $info->{pkgpath}, pkg => $info->{pkg},
            name => $name, recv => $recv_type, qual => $qual,
            file => $f, line => $line,
        };
        if ($recv_type) {
            $by_pkg_recv{"$info->{pkgpath}\t$recv_type\t$name"} = $id;
        } else {
            $by_pkg_name{"$info->{pkgpath}\t$name"} = $id;
        }
    }
}

sub extract_recv {
    my ($r) = @_;
    $r =~ s/^\s*//; $r =~ s/\s*$//;
    $r =~ s/^[\w.]+\s+//;
    $r =~ s/^\*//;
    $r =~ s/^[\w.]+\.//; # pkg.Type -> Type
    return $r;
}

# Build per-file and per-package type maps
my %pkg_types; # pkgpath => { var => TypeName }

for my $f (keys %fi) {
    my $pp = $fi{$f}{pkgpath};
    $pkg_types{$pp} //= {};
    my $c = $fi{$f}{clean};

    # receiver types from methods in this file
    while ($c =~ /\bfunc\s+\((\w+)\s+(\*?)([\w.]+)\)/g) {
        my ($v, $ptr, $t) = ($1, $2, $3);
        $t =~ s/^.*\.//;
        $pkg_types{$pp}{$v} = ($ptr ? '*' : '') . $t;
    }
    # param types
    while ($c =~ /\bfunc\s+(?:\([^)]*\)\s+)?\w+\s*\(([^)]*)\)/g) {
        my $params = $1;
        while ($params =~ /(\w+)\s+(\*?)([\w.]+)/g) {
            my ($v, $ptr, $t) = ($1, $2, $3);
            next if $v =~ /^(ctx|context|err|error)$/;
            $t =~ s/^.*\.//;
            $pkg_types{$pp}{$v} = ($ptr ? '*' : '') . $t unless $t =~ /^(int|string|bool|error|byte|any|Context|interface)$/;
        }
    }
    # short declarations
    while ($c =~ /(\w+)\s*:?=\s*(?:&)?(\*?)\s*([\w]+)\(/g) {
        my ($v, $ptr, $ctor) = ($1, $2, $3);
        if ($ctor =~ /^New([A-Z]\w*)/) {
            $pkg_types{$pp}{$v} = ($ptr || '') . $1;
        }
    }
    while ($c =~ /(\w+)\s*:?=\s*(?:&)?(\*?)([A-Z]\w*)\{/g) {
        my ($v, $ptr, $t) = ($1, $2, $3);
        $pkg_types{$pp}{$v} = ($ptr ? '*' : '') . $t;
    }
    # var declarations
    while ($c =~ /\bvar\s+(\w+)\s+(\*?)([\w.]+)/g) {
        my ($v, $ptr, $t) = ($1, $2, $3);
        $t =~ s/^.*\.//;
        $pkg_types{$pp}{$v} = ($ptr ? '*' : '') . $t;
    }
}

my %all; my %prod;

sub bump {
    my ($id, $f, $line) = @_;
    return unless $id;
    push @{ $all{$id} }, [$f, $line];
    push @{ $prod{$id} }, [$f, $line] unless is_test($f);
}

# Reserved words / builtins to skip as callees
my %skip = map { $_ => 1 } qw(
    if for switch return func go defer make new len cap append copy delete
    panic recover close complex real imag print println map struct interface
    int int8 int16 int32 int64 uint uint8 uint16 uint32 uint64 float32 float64
    bool byte rune string error any true false nil
);

for my $f (keys %fi) {
    my $info = $fi{$f};
    my $pp = $info->{pkgpath};
    my $line_num = 0;
    for my $line (@{ $info->{lines} }) {
        $line_num++;

        # selector calls: pkg.Func or var.Method
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($sel, $meth) = ($1, $2);
            next if $skip{$meth};

            my $id;
            if (exists $info->{imports}{$sel}) {
                my $ip = $info->{imports}{$sel};
                $id = $by_pkg_name{"$ip\t$meth"};
            } else {
                # method call - find matching recv type
                my $vt = $pkg_types{$pp}{$sel};
                if (defined $vt) {
                    my $rt = $vt; $rt =~ s/^\*//;
                    $id = $by_pkg_recv{"$pp\t$rt\t$meth"};
                    if (!$id) {
                        # search all internal packages for method on this type name
                        for my $did (keys %decls) {
                            my $d = $decls{$did};
                            next unless $d->{name} eq $meth && $d->{recv} eq $rt;
                            # prefer same package or imported package
                            if ($d->{pkgpath} eq $pp) { $id = $did; last; }
                            for my $a (keys %{ $info->{imports} }) {
                                if ($info->{imports}{$a} eq $d->{pkgpath}) { $id = $did; last; }
                            }
                            last if $id;
                        }
                    }
                }
            }
            bump($id, $f, $line_num);
        }

        # unqualified calls
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g) {
            my ($name) = $1;
            next if $skip{$name};
            my $id = $by_pkg_name{"$pp\t$name"};
            bump($id, $f, $line_num);
        }
    }
}

my @res;
for my $id (keys %decls) {
    push @res, {
        d => $decls{$id},
        prod => scalar(@{ $prod{$id} // [] }),
        all => scalar(@{ $all{$id} // [] }),
        callers => $all{$id} // [],
    };
}

@res = sort { $b->{prod} <=> $a->{prod} || $b->{all} <=> $a->{all} } @res;

print "=== TOP 40 production inbound calls to internal/ declarations ===\n";
for my $i (0..39) {
    last unless $i < @res;
    my $r = $res[$i];
    next if $r->{prod} == 0 && $r->{all} == 0;
    my $d = $r->{d};
    my $rel = $d->{file}; $rel =~ s/^\Q$REPO\E\/?//;
    printf "%d. %s :: %s\n   %s:%d  prod=%d all=%d\n",
        $i+1, $d->{pkgpath}, $d->{qual}, $rel, $d->{line}, $r->{prod}, $r->{all};
    show($r->{callers});
}

print "\n=== TOP 40 all-code ===\n";
@res = sort { $b->{all} <=> $a->{all} || $b->{prod} <=> $a->{prod} } @res;
for my $i (0..39) {
    last unless $i < @res;
    my $r = $res[$i];
    next if $r->{all} == 0;
    my $d = $r->{d};
    my $rel = $d->{file}; $rel =~ s/^\Q$REPO\E\/?//;
    printf "%d. %s :: %s\n   %s:%d  prod=%d all=%d\n",
        $i+1, $d->{pkgpath}, $d->{qual}, $rel, $d->{line}, $r->{prod}, $r->{all};
    show($r->{callers});
}

print "\nTotal internal decls: " . scalar(keys %decls) . "\n";

sub show {
    my ($cs) = @_;
    my %loc;
    for (@$cs) {
        my $rel = $_->[0]; $rel =~ s/^\Q$REPO\E\/?//;
        $loc{"$rel:$_->[1]"}++;
    }
    my @l = sort { $loc{$b} <=> $loc{$a} || $a cmp $b } keys %loc;
    print "   ";
    my $n = 0;
    for my $l (@l) {
        last if $n++ >= 12;
        print "; " if $n > 1;
        print $loc{$l} > 1 ? "$l(x$loc{$l})" : $l;
    }
    print " ..." if @l > 12;
    print "\n";
}

